          <div className="message-animate flex justify-start">
            <div className="chat-caan rounded-lg p-3 mr-12">
              <div className="flex items-center gap-2 mb-2">
                <div
                  className="w-2.5 h-2.5 rounded-full flex-shrink-0 pulse-red"
