                }}
              >
                <div className="flex items-center justify-between mb-1.5">
                  <div className="flex items-center gap-1.5">
                    <span style={{ color: agent.color, fontSize: '12px' }}>{agent.icon}</span>
                    <span
                      style={{
                        fontFamily: 'var(--font-orbitron), sans-serif',
